private function read(string$p,string$e):array{if(!is_file($p))throw new\RuntimeException($e);return json_decode((string)file_get_contents($p),true,512,JSON_THROW_ON_ERROR);}private function valid(array$r):bool{$d=$r['record_digest']??null;unset($r['record_digest']);return is_string($d)&&hash_equals($d,hash('sha256',CanonicalJson::encode($r)));}private function save(string$id,array$r):array{if(!is_dir($this->dispositions)&&!mkdir($this->dispositions,0770,true)&&!is_dir($this->dispositions))throw new\RuntimeException('S287_PROFILE_EXAMINATION_DISPOSITION_FAILED');$r['record_digest']=hash('sha256',CanonicalJson::encode($r));$p=$this->dispositions.'/'.$id.'.json';if(is_file($p)){if($this->read($p,'S288_PROFILE_EXAMINATION_DISPOSITION_CONFLICT')!==$r)throw new\RuntimeException('S288_PROFILE_EXAMINATION_DISPOSITION_CONFLICT');return$r;}$t=$p.'.tmp.'.bin2hex(random_bytes(6));if(false===file_put_contents($t,json_encode($r,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)."\n",LOCK_EX)||!rename($t,$p)){@unlink($t);throw new\RuntimeException('S287_PROFILE_EXAMINATION_DISPOSITION_FAILED');}return$r;}}
